/*
 * Host test for frame_codec.c: COBS + CRC-16 framing.
 *
 * Covers the reference vectors generated by protocol/gen_protocol.py (the same
 * bytes the web app's codec.ts is held to), round trips of every length and
 * zero density, frames far longer than one COBS block, and one case per
 * decoder rule. Each rejection case breaks exactly that rule and is valid
 * otherwise, and the decoder must be back in sync for the very next frame.
 */

#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>

#include "frame_codec.h"
#include "../host_protocol/golden_cases.h"

static int failures;

static void check(const char *name, int passed)
{
    printf("%-60s %s\n", name, passed ? "ok" : "FAIL");
    failures += passed ? 0 : 1;
}

/* Big enough for the long-frame cases; the protocol itself stays far below. */
#define RAW_MAX   1200U
#define WIRE_MAX  FRAME_CODEC_WIRE_BOUND(RAW_MAX)

static uint8_t        rxBuf[FRAME_CODEC_RX_BUF_BYTES(RAW_MAX)];
static frameDecoder_t dec;

/* Feeds wire bytes; returns the result of the LAST byte, and counts how many
 * non-NONE results came before it (they would be a bug in every case here). */
static frameResult_e feed(const uint8_t *wire, uint16_t len, int *earlyResults)
{
    frameResult_e r = FRAME_NONE;
    *earlyResults = 0;
    for (uint16_t i = 0U; i < len; i++) {
        r = frameDecoderPush(&dec, wire[i]);
        if (r != FRAME_NONE && i + 1U < len) {
            (*earlyResults)++;
        }
    }
    return r;
}

static bool decodesTo(const uint8_t *wire, uint16_t wireLen, const uint8_t *raw, uint16_t rawLen)
{
    int early;
    frameResult_e r = feed(wire, wireLen, &early);
    return early == 0 && r == FRAME_READY && dec.frameLen == rawLen
        && memcmp(dec.frame, raw, rawLen) == 0;
}

/* Tiny deterministic PRNG, so a failure reproduces. */
static uint32_t rngState = 0x12345678U;
static uint32_t rng(void)
{
    rngState ^= rngState << 13;
    rngState ^= rngState >> 17;
    rngState ^= rngState << 5;
    return rngState;
}


/* --- Reference vectors ---------------------------------------------------- */

static void testCrcCheckValue(void)
{
    static const uint8_t ascii[] = "123456789";
    check("crc16: CCITT-FALSE check value 0x29B1", frameCrc16(0xFFFFU, ascii, 9U) == 0x29B1U);

    /* Feeding in two parts gives the same CRC (frameEncode relies on it). */
    uint16_t split = frameCrc16(frameCrc16(0xFFFFU, ascii, 4U), ascii + 4, 5U);
    check("crc16: continues across calls", split == 0x29B1U);
}

static void testGoldenVectors(void)
{
    uint8_t wire[WIRE_MAX];
    bool encOk = true, decOk = true, crcOk = true;

    frameDecoderInit(&dec, rxBuf, sizeof(rxBuf));
    for (size_t i = 0U; i < GOLDEN_CODEC_COUNT; i++) {
        const goldenCodecCase_t *c = &goldenCodecCases[i];
        uint16_t n = frameEncode(c->raw, c->rawLen, NULL, 0U, wire, sizeof(wire));
        if (n != c->wireLen || memcmp(wire, c->wire, n) != 0) {
            printf("  encode mismatch: %s\n", c->name);
            encOk = false;
        }
        if (!decodesTo(c->wire, c->wireLen, c->raw, c->rawLen)) {
            printf("  decode mismatch: %s\n", c->name);
            decOk = false;
        }
        if (frameCrc16(0xFFFFU, c->raw, c->rawLen) != c->crc) {
            crcOk = false;
        }
    }
    check("golden: encoder matches gen_protocol.py byte for byte", encOk);
    check("golden: decoder recovers every reference frame", decOk);
    check("golden: CRC matches every reference vector", crcOk);
}


/* --- Round trips ----------------------------------------------------------- */

static void testRoundTrips(void)
{
    uint8_t raw[RAW_MAX];
    uint8_t wire[WIRE_MAX];
    bool ok = true, bounded = true, noZero = true;

    frameDecoderInit(&dec, rxBuf, sizeof(rxBuf));
    /* Every length up to past four COBS blocks, at five zero densities. */
    for (uint16_t len = 1U; len <= RAW_MAX && ok; len++) {
        for (uint32_t density = 0U; density < 5U && ok; density++) {
            for (uint16_t i = 0U; i < len; i++) {
                /* density 0: no zeros, 4: all zeros, between: random mix */
                uint32_t x = rng();
                raw[i] = (density == 0U) ? (uint8_t)(1U + x % 255U)
                       : (density == 4U) ? 0U
                       : ((x % 4U) < density) ? 0U : (uint8_t)(1U + (x >> 8) % 255U);
            }
            uint16_t split = (uint16_t)(rng() % (len + 1U));   /* head | body split point */
            uint16_t n = frameEncode(raw, split, raw + split, (uint16_t)(len - split), wire, sizeof(wire));
            bounded = bounded && n != 0U && n <= FRAME_CODEC_WIRE_BOUND(len);
            noZero  = noZero && memchr(wire, 0, (size_t)(n - 1U)) == NULL && wire[n - 1U] == 0U;
            ok      = ok && decodesTo(wire, n, raw, len);
        }
    }
    check("round trip: lengths 1..1200 x 5 zero densities x random split", ok);
    check("round trip: wire length within FRAME_CODEC_WIRE_BOUND", bounded);
    check("round trip: no 0x00 inside a frame, delimiter last", noZero);
    check("round trip: stats count every frame", dec.stats.frames == (uint32_t)RAW_MAX * 5U
                                                   && dec.stats.crcErrors == 0U && dec.stats.cobsErrors == 0U);
}

static void testFullBlocks(void)
{
    /* 254 non-zero bytes fill a block exactly (code 0xFF, no implied zero);
     * then a zero must still decode as a zero. */
    uint8_t raw[300], wire[WIRE_MAX];
    for (uint16_t i = 0U; i < 254U; i++) {
        raw[i] = (uint8_t)(1U + i % 255U);
    }
    raw[254] = 0U;
    raw[255] = 0x42U;

    frameDecoderInit(&dec, rxBuf, sizeof(rxBuf));
    uint16_t n = frameEncode(raw, 256U, NULL, 0U, wire, sizeof(wire));
    check("full block: first code byte is 0xFF", n != 0U && wire[0] == 0xFFU);
    check("full block: zero after a 0xFF block survives", decodesTo(wire, n, raw, 256U));
}


/* --- Decoder rules: one broken rule per case ------------------------------- */

static uint16_t encodeSample(uint8_t *wire, uint16_t cap)
{
    static const uint8_t raw[] = { 0x01, 0x00, 0x22, 0x33, 0x00, 0x44 };
    return frameEncode(raw, sizeof(raw), NULL, 0U, wire, cap);
}

static void testCrcError(void)
{
    uint8_t wire[64];
    uint16_t n = encodeSample(wire, sizeof(wire));
    int early;

    frameDecoderInit(&dec, rxBuf, sizeof(rxBuf));
    wire[3] ^= 0x01U;                         /* a data byte, still non-zero */
    frameResult_e r = feed(wire, n, &early);
    check("reject: one flipped data bit -> FRAME_ERR_CRC", r == FRAME_ERR_CRC && dec.stats.crcErrors == 1U);

    wire[3] ^= 0x01U;
    check("reject: next frame decodes after a CRC error", feed(wire, n, &early) == FRAME_READY);
}

static void testTruncated(void)
{
    uint8_t wire[64];
    uint16_t n = encodeSample(wire, sizeof(wire));
    int early;

    frameDecoderInit(&dec, rxBuf, sizeof(rxBuf));
    /* Drop the byte before the delimiter: the last block is now one short. */
    wire[n - 2U] = 0x00U;
    frameResult_e r = feed(wire, (uint16_t)(n - 1U), &early);
    check("reject: frame ends inside a block -> FRAME_ERR_COBS", r == FRAME_ERR_COBS && dec.stats.cobsErrors == 1U);

    n = encodeSample(wire, sizeof(wire));
    check("reject: next frame decodes after a truncated one", feed(wire, n, &early) == FRAME_READY);
}

static void testOverflow(void)
{
    static uint8_t small[FRAME_CODEC_RX_BUF_BYTES(8U)];
    uint8_t raw[9], wire[64];
    int early;

    for (uint8_t i = 0U; i < sizeof(raw); i++) {
        raw[i] = (uint8_t)(i + 1U);
    }
    frameDecoderInit(&dec, small, sizeof(small));
    uint16_t n = frameEncode(raw, 9U, NULL, 0U, wire, sizeof(wire));
    frameResult_e r = feed(wire, n, &early);
    check("reject: frame one byte over the buffer -> FRAME_ERR_OVERFLOW",
          r == FRAME_ERR_OVERFLOW && early == 0 && dec.stats.overflows == 1U);

    n = frameEncode(raw, 8U, NULL, 0U, wire, sizeof(wire));
    check("accept: frame exactly filling the buffer", decodesTo(wire, n, raw, 8U));
}

static void testShortAndEmpty(void)
{
    /* COBS of the single byte 0x05, no CRC: well-formed COBS, too short. */
    static const uint8_t tooShort[] = { 0x02, 0x05, 0x00 };
    /* A CRC alone: 0xFFFF is the correct CRC of zero raw bytes, so only the
     * "at least one raw byte" rule rejects it. */
    static const uint8_t crcOnly[]  = { 0x03, 0xFF, 0xFF, 0x00 };
    static const uint8_t empties[]  = { 0x00, 0x00, 0x00 };
    int early;

    frameDecoderInit(&dec, rxBuf, sizeof(rxBuf));
    frameResult_e r = feed(tooShort, sizeof(tooShort), &early);
    check("reject: frame without room for a CRC -> FRAME_ERR_SHORT", r == FRAME_ERR_SHORT && dec.stats.shortFrames == 1U);

    r = feed(crcOnly, sizeof(crcOnly), &early);
    check("reject: valid CRC but no raw byte -> FRAME_ERR_SHORT", r == FRAME_ERR_SHORT && dec.stats.shortFrames == 2U);

    r = feed(empties, sizeof(empties), &early);
    check("ignore: empty frames (repeated delimiters) are silent",
          r == FRAME_NONE && early == 0 && dec.stats.crcErrors == 0U && dec.stats.cobsErrors == 0U);
}

static void testResyncAfterGarbage(void)
{
    uint8_t wire[64];
    uint16_t n = encodeSample(wire, sizeof(wire));
    static const uint8_t raw[] = { 0x01, 0x00, 0x22, 0x33, 0x00, 0x44 };
    int early;

    frameDecoderInit(&dec, rxBuf, sizeof(rxBuf));
    /* Joining mid-stream: the tail of a frame we never saw the start of. */
    (void)feed(wire + 3, (uint16_t)(n - 3U), &early);
    check("resync: a frame after mid-stream garbage decodes", decodesTo(wire, n, raw, sizeof(raw)));

    /* frameDecoderReset drops a partial frame without counting an error. */
    (void)feed(wire, 4U, &early);
    uint32_t errorsBefore = dec.stats.crcErrors + dec.stats.cobsErrors;
    frameDecoderReset(&dec);
    check("reset: partial frame dropped, next frame decodes",
          decodesTo(wire, n, raw, sizeof(raw)) && dec.stats.crcErrors + dec.stats.cobsErrors == errorsBefore);
}


/* --- Encoder limits --------------------------------------------------------- */

static void testEncoderLimits(void)
{
    uint8_t wire[64];
    uint8_t guard[80];
    uint16_t full = encodeSample(wire, sizeof(wire));

    memset(guard, 0xAA, sizeof(guard));
    uint16_t n = encodeSample(guard, (uint16_t)(full - 1U));
    bool untouched = true;
    for (uint16_t i = (uint16_t)(full - 1U); i < sizeof(guard); i++) {
        untouched = untouched && guard[i] == 0xAAU;
    }
    check("encode: one byte short of room -> 0, nothing written past cap", n == 0U && untouched);
    check("encode: exact room succeeds", encodeSample(guard, full) == full);
    check("encode: empty input -> 0", frameEncode(NULL, 0U, NULL, 0U, wire, sizeof(wire)) == 0U);
    check("encode: NULL with a length -> 0", frameEncode(NULL, 3U, NULL, 0U, wire, sizeof(wire)) == 0U);
}


int main(void)
{
    testCrcCheckValue();
    testGoldenVectors();
    testRoundTrips();
    testFullBlocks();
    testCrcError();
    testTruncated();
    testOverflow();
    testShortAndEmpty();
    testResyncAfterGarbage();
    testEncoderLimits();

    printf("%s\n", failures ? "FAILED" : "all passed");
    return failures ? 1 : 0;
}
